draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // stick figure reading book
  ctx.beginPath();
  ctx.arc(W/2, H/2-120, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-90);
  ctx.lineTo(W/2-20, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-90);
  ctx.lineTo(W/2+20, H/2-70);
  ctx.stroke();

  // wisdom quote
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply wisdom', W/2, H/2+50 + 20*Math.sin(t));

  ctx.restore();
}
